package com.mediconnect.doctor.domain;
import java.util.UUID; import com.mediconnect.auth.domain.UserEntity; import com.mediconnect.shared.audit.AuditableEntity; import com.mediconnect.specialty.domain.SpecialtyEntity; import jakarta.persistence.*;
@Entity @Table(name="doctors") public class DoctorEntity extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false,unique=true) private UserEntity user; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="specialty_id",nullable=false) private SpecialtyEntity specialty; @Column(nullable=false,length=80) private String firstName; @Column(nullable=false,length=80) private String lastName; @Column(nullable=false,unique=true,length=80) private String medicalLicense; @Column(nullable=false) private boolean active=true; protected DoctorEntity(){} public DoctorEntity(UserEntity user,SpecialtyEntity specialty,String firstName,String lastName,String medicalLicense){this.user=user;this.specialty=specialty;this.firstName=firstName;this.lastName=lastName;this.medicalLicense=medicalLicense;this.active=true;} public UUID getId(){return id;} public UserEntity getUser(){return user;} public SpecialtyEntity getSpecialty(){return specialty;} public String getFirstName(){return firstName;} public String getLastName(){return lastName;} public String getMedicalLicense(){return medicalLicense;} public boolean isActive(){return active;} public void setActive(boolean active){this.active=active;} }
